package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Comment;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.jsoup.parser.Parser;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class Node_siblingIndex_TriageGen1Test {

    @Test
    public void testSiblingIndex_NodeHasNoSibling() {
        Node node = mock(Node.class);
        when(node.parent()).thenReturn(null);
        assertEquals(0, node.siblingIndex());
    }

    @Test
    public void testSiblingIndex_NodeHasSingleSibling() {
        Document doc = mock(Document.class);
        Node parent = mock(Node.class);
        when(doc.body()).thenReturn(parent);
        Node node = mock(Node.class);
        when(node.parent()).thenReturn(parent);
        when(parent.childNodes()).thenReturn(List.of(node));
        assertEquals(0, node.siblingIndex());
    }

    @Test
    public void testSiblingIndex_NodeHasMultipleSiblings() {
        Document doc = mock(Document.class);
        Node parent = mock(Node.class);
        when(doc.body()).thenReturn(parent);
        Node node1 = mock(Node.class);
        Node node2 = mock(Node.class);
        Node node3 = mock(Node.class);
        when(node1.parent()).thenReturn(parent);
        when(node2.parent()).thenReturn(parent);
        when(node3.parent()).thenReturn(parent);
        when(parent.childNodes()).thenReturn(List.of(node1, node2, node3));
        when(node1.siblingIndex()).thenReturn(0);
        when(node2.siblingIndex()).thenReturn(1);
        when(node3.siblingIndex()).thenReturn(2);
        assertEquals(2, node3.siblingIndex());
    }

    @Test
    public void testSiblingIndex_NodeHasNoParent() {
        Node node = mock(Node.class);
        when(node.parent()).thenReturn(null);
        assertEquals(-1, node.siblingIndex());
    }

    @Test
    public void testSiblingIndex_NodeHasParentButNoSiblings() {
        Document doc = mock(Document.class);
        Node parent = mock(Node.class);
        when(doc.body()).thenReturn(parent);
        Node node = mock(Node.class);
        when(node.parent()).thenReturn(parent);
        when(parent.childNodes()).thenReturn(List.of());
        assertEquals(-1, node.siblingIndex());
    }

    @Test
    public void testSiblingIndex_NodeHasParentAndSiblings() {
        Document doc = mock(Document.class);
        Node parent = mock(Node.class);
        when(doc.body()).thenReturn(parent);
        Node node1 = mock(Node.class);
        Node node2 = mock(Node.class);
        Node node3 = mock(Node.class);
        when(node1.parent()).thenReturn(parent);
        when(node2.parent()).thenReturn(parent);
        when(node3.parent()).thenReturn(parent);
        when(parent.childNodes()).thenReturn(List.of(node1, node2, node3));
        when(node1.siblingIndex()).thenReturn(0);
        when(node2.siblingIndex()).thenReturn(1);
        when(node3.siblingIndex()).thenReturn(2);
        assertEquals(2, node3.siblingIndex());
    }

    @Test
    public void testSiblingIndex_NodeHasSameSiblingIndexAsParent() {
        Document doc = mock(Document.class);
        Node parent = mock(Node.class);
        when(doc.body()).thenReturn(parent);
        Node node = mock(Node.class);
        when(node.parent()).thenReturn(parent);
        when(parent.childNodes()).thenReturn(List.of(node));
        assertEquals(-1, node.siblingIndex());
    }

    @Test
    public void testSiblingIndex_NodeHasNoParentAndNoSiblings() {
        Node node = mock(Node.class);
        when(node.parent()).thenReturn(null);
        assertEquals(-1, node.siblingIndex());
    }
}
